 internal static PacketObservation Aprs(string text=">Synthetic iGate test",DateTimeOffset? utc=null)=>new(utc??DateTimeOffset.UtcNow,"Synthetic live fixture",false,144390000,null,"FCS valid","N0CALL-7","APMRS","WIDE1-1*,WIDE2-1","UI",text,null,Convert.ToHexString(PacketTests.Frame(text)),SourceKey:"rf-test");
 internal static void Run(Action<bool,string> check)
 {
  bool Reject(Action f){try{f();return false;}catch{return true;}}var now=DateTimeOffset.UtcNow;var decl=new TxDeclaration("United States","K1ABC","General",true,true,true);var slot=DateTimeOffset.UnixEpoch.AddSeconds(Math.Ceiling(now.ToUnixTimeMilliseconds()/15000.0)*15);var plan=new WeakTxPlan("FT8",14074000,1500,"CQ K1ABC FN42",0,slot);WeakTxAuthorization.Validate(decl,plan,"synthetic");check(true,"General license data segment and own-call identification accepted");check(Reject(()=>WeakTxAuthorization.Validate(decl with{LicenseClass="Technician"},plan,"synthetic")),"Technician profile blocks HF FT8 outside 10 m");check(Reject(()=>WeakTxAuthorization.Validate(decl,plan with{DialHz=11175000},"synthetic")),"HFGCS/listening references never unlock TX");check(Reject(()=>WeakTxAuthorization.Validate(decl,plan with{DialHz=14150000},"synthetic")),"Entire digital emission must fit reviewed data segment");check(Reject(()=>WeakTxAuthorization.Validate(decl,plan with{Message="CQ W2XYZ FN42"},"synthetic")),"Encoded sender must match declaration");check(Reject(()=>WeakTxAuthorization.Validate(decl with{CurrentLicense=false},plan,"synthetic")),"License confirmation required on every armed session");string permit=WeakTxAuthorization.Issue(decl,plan,"synthetic");check(WeakTxAuthorization.Read(permit,plan,"synthetic").Plan==plan,"Digital worker permit binds exact message, slot, gain and device");check(Reject(()=>WeakTxAuthorization.Read(permit,plan with{AudioHz=1600},"synthetic")),"Digital permit blocks edited audio offset");check(Reject(()=>WeakTxAuthorization.Read(permit,plan,"other")),"Digital permit blocks a different device");
  foreach(string mode in new[]{"FT8","FT4","WSPR"}){var next=WeakTxPlan.NextSlot(now,mode,true);var p=plan with{Mode=mode,SlotUtc=next,Message=mode=="WSPR"?"K1ABC FN42 0":"CQ K1ABC FN42"};p.Validate();check(next>=now.AddSeconds(4),mode+" scheduler reserves startup lead");check(mode=="WSPR"||(long)(next.ToUnixTimeMilliseconds()/1000.0/p.Period)%2==1,mode+" scheduled parity is correct");byte[] tones=WeakWaveform.Encode(p);check(tones.Length==p.Symbols&&tones.Distinct().Count()>1,mode+" encoder produces complete standard channel symbols");float[] audio=WeakWaveform.Audio(p,tones);check(audio.Take((int)(p.Lead*12000)).All(s=>s==0)&&audio.All(float.IsFinite),mode+" waveform has protocol lead and finite phase-shaped samples");var padded=new float[(int)(p.Period*12000)];Array.Copy(audio,padded,Math.Min(audio.Length,padded.Length));string text=Decode(mode,padded);check(text.Contains(mode=="WSPR"?"K1ABC":"CQ K1ABC FN42"),mode+" newly encoded waveform decodes end to end");}
  var iqPlan=plan with{Mode="FT4",SlotUtc=WeakTxPlan.NextSlot(now,"FT4",false)};var iqAudio=ActualIqAudio(iqPlan);check(Decode("FT4",iqAudio).Contains("CQ K1ABC FN42"),"Actual quantized streaming I/Q generator decodes after independent real-channel extraction");var wp=plan with{Mode="WSPR",SlotUtc=WeakTxPlan.NextSlot(now,"WSPR",false),Message="K1ABC FN42 0"};var late=new WeakIqSource(wp,WeakWaveform.Encode(wp),80L*WeakIqSource.Rate);var block=new byte[64000];check(late.Read(block)==block.Length&&block.Distinct().Count()>16,"WSPR I/Q remains modulated after 80 seconds (phase-table index cannot overflow)");
  check(Reject(()=>WeakWaveform.Encode(plan with{Message="HELLO WORLD"})),"Unsupported free-text TX cannot silently become a different format");check(Reject(()=>(plan with{Mode="WSPR",SlotUtc=WeakTxPlan.NextSlot(now,"WSPR",false),Message="K1ABC FN42 24"}).Validate()),"WSPR rejects unrepresentable power levels");
  var q=new WeakQso("K1ABC","FN42");q.Answer("W2XYZ",-12,now.AddMinutes(-1));PacketObservation Row(string message)=>Update043Tests.Row(message,utc:now);check(!q.Observe(Row("N3TEST W2XYZ -10"),now),"Other-destination report cannot advance selected QSO");check(!q.Observe(Row("K1ABC W2XYZ -10") with{Replay=true},now),"Replay cannot advance transmit exchange");check(q.Observe(Row("K1ABC W2XYZ -10"),now)&&q.Message=="W2XYZ K1ABC R-12","Answering QSO advances received report to reciprocal R-report");check(q.Observe(Row("K1ABC W2XYZ RR73"),now)&&q.Message=="W2XYZ K1ABC 73","Answering QSO emits final 73 after peer RR73");q.Sent();check(q.Complete,"Final 73 completes and stops exchange");q=new("K1ABC","FN42");q.Answer("W2XYZ",-8,now.AddMinutes(-1));check(q.Observe(Row("K1ABC W2XYZ FN20"),now)&&q.Message=="W2XYZ K1ABC -08","Calling-side received grid advances to report");check(q.Observe(Row("K1ABC W2XYZ R-09"),now)&&q.Message=="W2XYZ K1ABC RR73","Calling-side received R-report advances to RR73");check(q.Observe(Row("K1ABC W2XYZ 73"),now)&&q.Complete,"Received peer 73 completes QSO");
  string? line=AprsInternetPacket.Prepare(Aprs(),"K1ABC-10",now);check(line=="N0CALL-7>APMRS,WIDE1-1*,WIDE2-1,qAO,K1ABC-10:>Synthetic iGate test","iGate retains original body/path and uses receive-only qAO");check(AprsInternetPacket.Prepare(Aprs() with{Replay=true},"K1ABC-10",now)==null,"iGate excludes recordings");check(AprsInternetPacket.Prepare(Aprs() with{ObservedUtc=now.AddMinutes(-1)},"K1ABC-10",now)==null,"iGate never uploads old backlog");check(AprsInternetPacket.Prepare(Aprs("GENERIC AX25 TEXT"),"K1ABC-10",now)==null,"Generic non-APRS AX.25 UI payloads are not reported");check(AprsInternetPacket.Prepare(Aprs("?APRS?"),"K1ABC-10",now)==null,"iGate drops generic queries");check(AprsInternetPacket.Prepare(Aprs("}N0TEST>APRS,TCPIP*:>test"),"K1ABC-10",now)==null,"iGate blocks Internet-origin third-party frames");check(AprsInternetPacket.Prepare(Aprs("}N0TEST>APRS,NOGATE:>test"),"K1ABC-10",now)==null,"iGate honors third-party NOGATE");check(AprsInternetPacket.Prepare(Aprs("}N0TEST>APRS,WIDE1-1:>test"),"K1ABC-10",now)=="N0TEST>APRS,WIDE1-1,qAO,K1ABC-10:>test","RF-only third-party header is correctly unwrapped");check(AprsInternetPacket.Prepare(Aprs(">test\r\nuser BAD pass 1"),"K1ABC-10",now)==null,"RF content cannot inject APRS-IS lines");check(AprsInternetPacket.Prepare(Aprs(new string('x',490)),"K1ABC-10",now)==null,"APRS-IS line respects 512-byte limit including CRLF");var corrupt=PacketTests.Frame(">bad");corrupt[^1]^=1;check(AprsInternetPacket.Prepare(Aprs() with{RawHex=Convert.ToHexString(corrupt)},"K1ABC-10",now)==null,"iGate independently rejects bad original FCS");check(AprsInternetPacket.Prepare(Aprs() with{RawHex=Convert.ToHexString(PacketTests.Frame("test",control:19))},"K1ABC-10",now)==null,"iGate accepts only UI control and no-layer-3 PID");
  check(BeaconSchedule.Expected(DateTimeOffset.UnixEpoch,0)=="4U1UN"&&BeaconSchedule.Expected(DateTimeOffset.UnixEpoch.AddSeconds(10),1)=="4U1UN","Beacon schedule band offsets follow ten-second stagger");check(BeaconSchedule.Expected(DateTimeOffset.UnixEpoch.AddSeconds(180),0)=="4U1UN","Beacon schedule repeats every three minutes");check(Js8Bridge.Command("TX.SEND_MESSAGE","W2XYZ TEST").Contains("\"params\":{}"),"JS8 API always includes required params object");Task.Run(()=>Network(check)).GetAwaiter().GetResult();
 }
 internal static string Decode(string mode,float[] audio){var start=new ProcessStartInfo(Path.Combine(AppContext.BaseDirectory,"Decoders","RadioData","mrs-weak.exe")){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add(mode);using var process=Process.Start(start)!;var read=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();process.StandardInput.BaseStream.Write(BitConverter.GetBytes(audio.Length));byte[] data=new byte[audio.Length*4];Buffer.BlockCopy(audio,0,data,0,data.Length);process.StandardInput.BaseStream.Write(data);process.StandardInput.Close();if(!process.WaitForExit(60000)){process.Kill(true);throw new IOException(mode+" TX loopback decode timeout");}if(process.ExitCode!=0)throw new IOException(errors.GetAwaiter().GetResult());return read.GetAwaiter().GetResult();}
 private static async Task Network(Action<bool,string> check){using var timeout=new CancellationTokenSource(TimeSpan.FromSeconds(8));var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{int port=((IPEndPoint)listener.LocalEndpoint).Port;using var gate=new AprsInternet();gate.Enable(new("K1ABC-10","12345","127.0.0.1",port));using var server=await listener.AcceptTcpClientAsync(timeout.Token);using var stream=server.GetStream();using var reader=new StreamReader(stream,Encoding.Latin1,leaveOpen:true);string? login=await reader.ReadLineAsync(timeout.Token);check(login!=null&&login.StartsWith("user K1ABC-10 pass 12345 vers MRS "),"Local APRS-IS server receives explicit station/software login");check(!gate.Queue(Aprs(),DateTimeOffset.UtcNow),"No upload before verified login");await stream.WriteAsync(Encoding.ASCII.GetBytes("# logresp K1ABC-10 verified, TESTSERVER\r\n"),timeout.Token);for(int n=0;n<30&&!gate.Verified;n++)await Task.Delay(20,timeout.Token);var now=DateTimeOffset.UtcNow;check(gate.Verified&&gate.Queue(Aprs(),now),"Verified mock APRS-IS session accepts fresh RF frame");check(!gate.Queue(Aprs(),now),"iGate duplicates suppressed across changing RF observations");string? packet=await reader.ReadLineAsync(timeout.Token);check(packet!=null&&packet.Contains(",qAO,K1ABC-10:"),"Local server receives one receive-only iGate packet");gate.Disable();check(!gate.Verified&&!gate.Queue(Aprs(),now),"Disable immediately stops further APRS reports");}finally{listener.Stop();}
  var api=new TcpListener(IPAddress.Loopback,0);api.Start();try{using var bridge=new Js8Bridge();var received=new TaskCompletionSource<string>();bridge.Received+=s=>received.TrySetResult(s);await bridge.Connect(((IPEndPoint)api.LocalEndpoint).Port);using var peer=await api.AcceptTcpClientAsync(timeout.Token);using var stream=peer.GetStream();using var reader=new StreamReader(stream,leaveOpen:true);await bridge.Send("RIG.GET_FREQ");string? request=await reader.ReadLineAsync(timeout.Token);check(request!=null&&request.Contains("RIG.GET_FREQ")&&request.Contains("\"params\":{}"),"JS8 bridge writes valid commands to local mock backend");await stream.WriteAsync(Encoding.UTF8.GetBytes("{\"type\":\"RX.ACTIVITY\",\"params\":{},\"value\":\"SYNTHETIC\"}\n"),timeout.Token);check((await received.Task.WaitAsync(timeout.Token)).Contains("SYNTHETIC"),"JS8 bridge receives framed local API events");}finally{api.Stop();}}
 internal static float[] ActualIqAudio(WeakTxPlan p){var iq=new WeakIqSource(p,WeakWaveform.Encode(p));var audio=new float[(int)(p.Period*12000)];byte[] buffer=new byte[131072];int sample=0;while(iq.Position<iq.Samples){long begin=iq.Position;int bytes=iq.Read(buffer);if(bytes==0)break;long end=begin+bytes/2;while(sample<audio.Length){long at=(long)Math.Round(sample*(double)WeakIqSource.Rate/12000);if(at>=end)break;if(at>=begin)audio[sample]=unchecked((sbyte)buffer[(int)(at-begin)*2])/40f;sample++;}}return audio;}
 internal static string Export(string directory){Directory.CreateDirectory(directory);foreach(string mode in new[]{"FT8","FT4","WSPR"}){var p=new WeakTxPlan(mode,mode=="WSPR"?14095600:14074000,1500,mode=="WSPR"?"K1ABC FN42 0":"CQ K1ABC FN42",0,WeakTxPlan.NextSlot(DateTimeOffset.UtcNow,mode,false));var samples=mode=="WSPR"?WeakWaveform.Audio(p,WeakWaveform.Encode(p)):ActualIqAudio(p);using var wav=new WaveFileWriter(Path.Combine(directory,"synthetic-tx-"+mode.ToLowerInvariant()+".wav"),new WaveFormat(12000,16,1));for(int i=0;i<(int)(p.Period*12000);i++)wav.WriteSample(i<samples.Length?samples[i]:0);}return "PASS: synthetic waveforms exported; no RF/network activity";}
